            if (((d.name_hash == planned.name_hash) and (@as(u8, @bitCast(d.behavior)) == @as(u8, @bitCast(planned.behavior))))) {
                return LiveEdge{ .dep_id = (sl.off + @as(DependencyID, @intCast(idx))), .pkg_name = pkg_name };
            }
            idx = (idx + 1);
        }
        return null;
}

pub fn enqueuePinned(manager: *PackageManager, dep_id: DependencyID, to_version: Semver.Version) !void {
        const target = manager.lockfile.buffers.resolutions.items[@as(usize, @intCast(dep_id))];
        const pkg_name = manager.lockfile.packages.items(.name)[@as(usize, @intCast(target))];
        _ = try enqueuePinnedAs(manager, dep_id, pkg_name, to_version);
}

pub fn enqueuePinnedAs(manager: *PackageManager, dep_id: DependencyID, pkg_name: Semver.String, to_version: Semver.Version) !void {
        const row = manager.lockfile.buffers.dependencies.items[@as(usize, @intCast(dep_id))];
        var behavior = row.behavior;
        _ = &behavior;
        behavior.peer = false;
        const pinned = Dependency{ .name = (if (@typeInfo(@TypeOf(row)) == .@"enum" or @typeInfo(@TypeOf(row)) == .@"union") @tagName(row) else row.name), .name_hash = row.name_hash, .behavior = behavior, .version = Dependency.Version{ .tag = .npm, .literal = .{}, .value = .{ .npm = Dependency.Version.NpmInfo{ .name = pkg_name, .version = Semver.Query.Group.from(to_version), .is_alias = true } } } };
        manager.lockfile.buffers.resolutions.items[cp_cast_int(usize, dep_id)] = invalid_package_id;
        _ = try manager.enqueueDependencyWithMain(dep_id, (&pinned), invalid_package_id, false);
}
